// th16_s7_w06 — TH16 Extra stage 7, MainSub05 (GirlD02 four double-sided waves).
// Source: st07.ecl.txt MainSub05 1275-1290 / GirlD02 760-771 / GirlD02_at 773-790 / GirlD02_at2 792-816.
// Extra is implemented as a single rank (GVAR_RANK == RANK_EXTRA == 4); source has no difficulty masks.

const TH16_RICE: int = 480;      // source etSprite type 8 -> TH16_RICE (base radius 2.4), color 6

const TIME_LIMIT: int = 1624;    // 120 shell buffer + ~1500 source window + 4 startup
const OPENING_BUFFER: int = 120;

// Source EX etEx(0,0,2,1,...) = ANIM a=1: omit the birth animation, but keep its
// `position -= 4*velocity` retreat (speed 1 -> 4px backwards along the fired angle).
// Source EX etEx(0,0,2097152,120,...,2.0,-999999) = VELTIME: over 120 frames ramp the
// scalar speed 1 -> 2 while preserving the bullet's direction (s=-999999 keeps angle).
xformdef VELTIME_RAMP {
    step_speed(2fx, 120);
    wait(120);
}

// Source GirlD02_at2: one emitter config, then 32 iterations of
// (6-way fan, wait 20, 5-way fan, wait 20) with a fresh random base angle each iteration.
async sub girl_d02_fire() {
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 6);
    sh_aim(0, 1);              // source etAim(0,0): aimed fan
    sh_ring(0, 0);             // fan, not a ring
    sh_speed(0, 1fx, 0fx);     // source etSpeed(0,1,1): single layer speed 1
    sh_dist(0, -4fx);          // source ANIM birth retreat position -= 4*velocity
    sh_xform(0, VELTIME_RAMP);
    var k: int = 0;
    while k < 32 {             // source $A = 32; `if ($A--)` body runs 32 times
        // source %RANDF2 * 0.17453292f (RANDF2 in [-1,1], 10deg in BAM = 1820)
        var r: int = rand(65536) - 32768;
        sh_angle(0, ((r * 1820) / 32768) as angle, 20deg);  // spread 0.34906584f = 20deg
        sh_count(0, 6, 1);
        sh_fire(0);
        wait(20);
        sh_count(0, 5, 1);
        sh_fire(0);
        wait(20);
        k = k + 1;
    }
}

// Source GirlD02 -> GirlD02_at. dropMain/dropExtra/dropArea/dropSeason are reward-only -> omitted.
// mirror==0 is the left (-224) enemy; mirror==1 is the right (+224) `M` enemy (x-axis mirror).
async sub girl_d02(mirror: int) {
    set_invuln(65535);          // training shell: real enemy is invulnerable
    set_hurtbox(12fx);          // source setHurtbox(24,24): circular branch radius 24*0.5
    set_hitbox(8fx);            // source setHitbox(16,16): body radius 16*0.5
    // source moveVel(-1.3744467,1) = -78.75deg; moveVelTime(60,mode1,-0.19634955,1) = -11.25deg;
    // final moveVelTime(60,mode0,0,1) = 0deg. Mirror reflects angles across x=0: theta -> 180deg - theta.
    var a0: angle = -14336bam;  // -78.75deg
    var a1: angle = -2048bam;   // -11.25deg
    var a2: angle = 0deg;
    if mirror != 0 {
        a0 = 180deg - a0;
        a1 = 180deg - a1;
        a2 = 180deg - a2;
    }
    move_vel(0, a0, 1fx, EASE_LINEAR);
    move_vel(60, a1, 1fx, EASE_QUAD_IN);   // source mode1 = quadratic in
    wait(60);
    spawn girl_d02_fire();                 // source @GirlD02_at2() async
    wait(120);
    move_vel(60, a2, 1fx, EASE_LINEAR);    // source mode0 = linear
    loop { wait(1000); }                   // source GirlD02_at loops forever (enemy exits offscreen)
}

async sub pattern() {
    wait(OPENING_BUFFER);   // shell buffer, does not replace source MainSub05 wait(80)
    wait(80);               // source MainSub05:1277
    _ = spawn_enemy(224fx, 448fx, 800, 0, 800, 0, girl_d02(1));
    _ = spawn_enemy(-224fx, 448fx, 800, 0, 800, 0, girl_d02(0));
    wait(200);              // source MainSub05:1280
    _ = spawn_enemy(224fx, 448fx, 800, 0, 800, 0, girl_d02(1));
    _ = spawn_enemy(-224fx, 448fx, 800, 0, 800, 0, girl_d02(0));
    wait(200);              // source MainSub05:1283
    _ = spawn_enemy(224fx, 448fx, 800, 0, 800, 0, girl_d02(1));
    _ = spawn_enemy(-224fx, 448fx, 800, 0, 800, 0, girl_d02(0));
    wait(200);              // source MainSub05:1286
    _ = spawn_enemy(224fx, 448fx, 800, 0, 800, 0, girl_d02(1));
    _ = spawn_enemy(-224fx, 448fx, 800, 0, 800, 0, girl_d02(0));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
